pr.solution:
def F1(c):
    if "0" <= c <= "9":
        return ord(c) - ord("0")
    return ord(c) - ord("A") + 10

def hex2dec(h):
    dec = 0
    length = len(h)
    for i in range(length):
        digit = length - 1 - i
        dec = dec + F1(h[i]) * 16 ** digit
    return dec

